import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9b5a0');scene.fog=new THREE.FogExp2('#a9b5a0',.0095);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,260);
const hemi=new THREE.HemisphereLight('#e7ecd5','#504739',2.05);scene.add(hemi);const sun=new THREE.DirectionalLight('#ffe3ae',3.2);sun.position.set(-32,54,24);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,rough=.86,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat('#758367');const stoneMat=mat('#756f5c');const darkStone=mat('#474b3e');const wood=mat('#674a32');const leaves=[mat('#465f48'),mat('#52694b'),mat('#69784f'),mat('#384f40')];
const world=new THREE.Group();scene.add(world);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(230,230,1,1),groundMat);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;world.add(floor);
// irregular meadow and path patches
function patch(x,z,sx,sz,color,rot=0){const m=new THREE.Mesh(new THREE.CircleGeometry(1,32),mat(color));m.rotation.x=-Math.PI/2;m.rotation.z=rot;m.position.set(x,.012,z);m.scale.set(sx,sz,1);m.receiveShadow=true;world.add(m)}
for(let i=0;i<36;i++){const a=i*2.4;patch(Math.sin(a)*31,Math.cos(a*1.3)*30,3+Math.random()*7,2+Math.random()*5,i%3?'#718064':'#827f5d',a)}
// winding pale dirt trail
const roadPts=[new THREE.Vector3(-65,.035,17),new THREE.Vector3(-40,.035,13),new THREE.Vector3(-19,.035,9),new THREE.Vector3(-2,.035,1),new THREE.Vector3(16,.035,-2),new THREE.Vector3(36,.035,-17),new THREE.Vector3(66,.035,-26)];
const roadCurve=new THREE.CatmullRomCurve3(roadPts);const road=new THREE.Mesh(new THREE.TubeGeometry(roadCurve,90,3.8,8,false),mat('#a29470'));road.scale.y=.007;road.position.y=.045;road.receiveShadow=true;world.add(road);
function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,rt,rb,h,material,n=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,n),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function tree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);cylinder(g,0,1.35,0,.2,.34,2.7,wood,7);for(let i=0;i<3;i++){const c=new THREE.Mesh(new THREE.IcosahedronGeometry(1.05-i*.17,1),leaves[Math.floor(Math.random()*leaves.length)]);c.position.set((Math.random()-.5)*.4,2.3+i*.72,(Math.random()-.5)*.35);c.scale.set(1.15,.88,1);c.castShadow=true;g.add(c)}world.add(g);return g}
for(let i=0;i<90;i++){let x=(Math.random()-.5)*155,z=(Math.random()-.5)*140;if(Math.abs(x)<11&&Math.abs(z)<12)continue;if(Math.abs(z-(11-x*.25))<7)continue;tree(x,z,.72+Math.random()*.75)}
// little council outpost and ruins
function hut(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);box(g,0,1.4,0,4*s,2.8*s,3.6*s,mat('#746249'));const roof=new THREE.Mesh(new THREE.ConeGeometry(3.2*s,1.8*s,4),mat('#51483a'));roof.rotation.y=Math.PI/4;roof.position.y=3.45*s;roof.castShadow=true;g.add(roof);box(g,0,.85,1.85*s,.85*s,1.7*s,.12,mat('#382c22'));box(g,-1.05*s,1.75*s,1.83*s,.55*s,.75*s,.12,mat('#d1ae65',.4));world.add(g)}
hut(-16,-7,1.15);hut(-22,-12,.8);hut(14,12,.72);
// weathered obelisk trail markers
for(const [x,z] of [[-5,6],[24,-9],[-30,9]]){const g=new THREE.Group();g.position.set(x,0,z);cylinder(g,0,.8,0,.52,.7,1.6,stoneMat,6);cylinder(g,0,1.9,0,.3,.5,1.1,darkStone,6);const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.23),mat('#d7ba6a',.35,.2));gem.position.y=2.58;g.add(gem);world.add(g)}
// stone arches, shrine and dungeon entrance
function arch(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);box(g,-2.05*scale,2.1*scale,0,.8*scale,4.2*scale,.9*scale,stoneMat);box(g,2.05*scale,2.1*scale,0,.8*scale,4.2*scale,.9*scale,stoneMat);box(g,0,4.3*scale,0,4.9*scale,.7*scale,1.05*scale,stoneMat);box(g,0,4.72*scale,0,2.8*scale,.18*scale,1.08*scale,mat('#b69b5a'));world.add(g);return g}
const portal=arch(39,-24,1.12);const portalGlow=new THREE.Mesh(new THREE.PlaneGeometry(3.3,3.6),new THREE.MeshBasicMaterial({color:'#86c8bc',transparent:true,opacity:.38,side:THREE.DoubleSide}));portalGlow.position.set(39,2.3,-23.48);portal.add(portalGlow);
const portalRing=new THREE.Mesh(new THREE.TorusGeometry(1.2,.045,8,48),new THREE.MeshBasicMaterial({color:'#d8c077'}));portalRing.position.set(39,2.1,-23.36);portal.add(portalRing);
// small rocks, grass clumps
for(let i=0;i<70;i++){const x=(Math.random()-.5)*130,z=(Math.random()-.5)*110;if(Math.abs(x)<8&&Math.abs(z)<10)continue;const r=new THREE.Mesh(new THREE.DodecahedronGeometry(.3+Math.random()*.55,0),i%3?stoneMat:darkStone);r.position.set(x,.25,z);r.scale.y=.6;r.rotation.set(Math.random(),Math.random(),Math.random());r.castShadow=true;r.receiveShadow=true;world.add(r)}
// player avatar
const player=new THREE.Group();scene.add(player);player.position.set(0,0,10);
const skin=mat('#bb906b'),armor=mat('#354740',.62,.12),trim=mat('#c5a45d',.5,.4),cloth=mat('#8c6841'),steel=mat('#8e9890',.38,.55);
const body=new THREE.Group();player.add(body);
cylinder(body,0,1.05,0,.35,.42,1.05,armor,8);const torso=body.children[0];torso.scale.z=.72;
const head=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),skin);head.position.set(0,1.78,0);head.castShadow=true;body.add(head);
const helm=new THREE.Mesh(new THREE.ConeGeometry(.29,.38,6),trim);helm.position.set(0,2.05,0);helm.castShadow=true;body.add(helm);
box(body,-.45,1.25,0,.22,.52,.42,trim);box(body,.45,1.25,0,.22,.52,.42,trim);
for(const x of [-.19,.19]){cylinder(body,x,.37,0,.13,.16,.68,mat('#353532'),7);cylinder(body,x,.12,.08,.17,.18,.18,wood,7)}
const cape=box(body,0,1.13,-.32,.48,.92,.09,cloth);cape.rotation.x=-.08;
// held axe on right, animated swing pivot
const weapon=new THREE.Group();weapon.position.set(.56,1.05,.12);body.add(weapon);box(weapon,0,.05,.22,.09,.09,.95,wood);box(weapon,.02,.47,.27,.12,.8,.1,steel);const blade=new THREE.Mesh(new THREE.ConeGeometry(.34,.62,4),steel);blade.rotation.z=Math.PI/2;blade.position.set(.23,.55,.27);weapon.add(blade);const axeGold=new THREE.Mesh(new THREE.TorusGeometry(.24,.025,5,12,Math.PI),trim);axeGold.position.set(.1,.48,.27);axeGold.rotation.z=-Math.PI/2;weapon.add(axeGold);
// camera settings, entity and combat state
let yaw=0,pitch=.28,dragging=false,lastX=0,lastY=0,attackTimer=0,dodgeTimer=0,hitFlash=0,health=100,stamina=100,inventory=[],selectedItem=null,kills=0,currency=1240,modalOpen=false,worldMode='wilds',lastToast=0;
const keys={};
const enemies=[],drops=[];
const enemyNames=['Corrupt Magistrate','Toll Baron','Council Enforcer','Crooked Minister','Lobbyist Knight','Favor Broker'];
const dropTypes=['weapon','helmet','chest','gloves','boots','amulet','ring','offhand','belt','shoulders','cloak','relic'];
const gearNames={weapon:['Ashen Oathblade','Ironbark Greataxe','Gavel of Last Resort','Verdict Splitter','Muckraker','People’s Edge','Censure Maul','Tithe Collector'],helmet:['Crown of Empty Promises','Briarbound Coif','Watchman’s Hood','Helm of the Unbought'],chest:['Commonweal Hauberk','Bailiff’s Coat','Verdant Brigandine','Unpaid Debtor’s Vest'],gloves:['Fist of the Public','Silk-Palm Grips','Reformist Gauntlets'],boots:['Boots of Due Process','Mudslogger Treads','Fast Campaigners'],amulet:['Pendant of Plain Truth','Corruption Ward','Voter’s Keepsake'],ring:['Ring of Honest Accounts','Seal of the Smallfolk','Signet of No Favors'],offhand:['Shield of Open Books','Petitioner's Buckler','Ledger of Rebuke'],belt:['Belt of Broken Red Tape','Sash of the Wilds'],shoulders:['Pauldrons of Recall','Shoulders of Scrutiny'],cloak:['Cloak of the Unheard','Banner of the People'],relic:['Golden Quill of Audits','Miniature Ballot Box','Unsealed Ledger']};
const rarities=[['COMMON','#c5c7bc',52],['UNCOMMON','#71bd7c',27],['RARE','#64a9dc',14],['EPIC','#bb82e7',6],['LEGENDARY','#efb84d',1]];
function makeEnemy(x,z,boss=false){const g=new THREE.Group();g.position.set(x,0,z);const skinE=mat(boss?'#b18a72':'#a97f68');const suit=mat(boss?'#582e32':'#55413d');const goldE=mat('#bd9a57',.45,.3);const face=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),skinE);face.position.y=1.72;g.add(face);const coat=new THREE.Mesh(new THREE.CylinderGeometry(.34,.48,1.05,8),suit);coat.position.y=1.02;g.add(coat);box(g,-.4,1.2,0,.2,.48,.3,suit);box(g,.4,1.2,0,.2,.48,.3,suit);for(const xx of [-.18,.18])cylinder(g,xx,.35,0,.13,.16,.65,mat('#292a28'),7);const tie=box(g,0,1.2,.27,.09,.58,.04,goldE);tie.rotation.z=.07;const hat=new THREE.Mesh(new THREE.CylinderGeometry(.28,.28,.13,10),goldE);hat.position.y=2.03;g.add(hat);const hp= new THREE.Group();hp.position.set(0,2.35,0);g.add(hp);const bg=box(hp,0,0,0,1.1,.07,.07,mat('#311d1c'));const fill=box(hp,0,.01,.04,1,.04,.04,mat('#d25e4b'));fill.position.x=0;g.userData={hp,fill,max:boss?150:90,hpNow:boss?150:90,boss,name:enemyNames[Math.floor(Math.random()*enemyNames.length)],attack:Math.random()*2,hit:0};g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(g);enemies.push(g);return g}
for(const p of [[-9,1],[9,-4],[-28,-1],[25,4],[5,-20],[31,-12]])makeEnemy(...p);
function createDrop(x,z,forceType){const type=forceType||dropTypes[Math.floor(Math.random()*dropTypes.length)];const r=Math.random()*100;let rarity=rarities[0];for(const q of rarities){if(r<q[2]){rarity=q;break}}
const item={id:Date.now()+Math.random(),type,name:gearNames[type][Math.floor(Math.random()*gearNames[type].length)],rarity:rarity[0],color:rarity[1],level:14+Math.floor(Math.random()*8),power:Math.floor(8+Math.random()*24),x,z};const g=new THREE.Group();g.position.set(x,0,z);const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.26),mat(rarity[1],.25,.25));gem.position.y=.62;gem.castShadow=true;g.add(gem);const ring=new THREE.Mesh(new THREE.TorusGeometry(.39,.025,6,24),new THREE.MeshBasicMaterial({color:rarity[1],transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.y=.18;g.add(ring);const light=new THREE.PointLight(rarity[1],1.7,4);light.position.y=.8;g.add(light);scene.add(g);drops.push({item,g});return item}
function gearIcon(type){return ({weapon:'⚔',helmet:'♙',chest:'♜',gloves:'♧',boots:'⌁',amulet:'◇',ring:'◉',offhand:'◈',belt:'═',shoulders:'⌑',cloak:'♟',relic:'✧'})[type]||'✧'}
function showToast(title,sub){const el=document.querySelector('#toast');el.querySelector('b').textContent=title;el.querySelector('small').textContent=sub;el.classList.add('visible');clearTimeout(lastToast);lastToast=setTimeout(()=>el.classList.remove('visible'),2700)}
function damageEnemy(enemy,amount){const u=enemy.userData;u.hpNow-=amount;u.hit=.22;u.fill.scale.x=Math.max(.02,u.hpNow/u.max);u.fill.position.x=-(1-u.hpNow/u.max)*.5;const f=document.querySelector('#combat-float');f.textContent='-'+amount;f.classList.remove('pop');void f.offsetWidth;f.classList.add('pop');if(u.hpNow<=0){scene.remove(enemy);enemies.splice(enemies.indexOf(enemy),1);kills++;document.querySelector('#quest-count').textContent=`${Math.min(kills,3)} / 3`;document.querySelector('#journal-progress').textContent=`${Math.min(kills,3)} / 3`;currency+=25+Math.floor(Math.random()*20);document.querySelector('#currency').textContent=currency.toLocaleString();createDrop(enemy.position.x+.8,enemy.position.z+.3);if(kills===1)createDrop(enemy.position.x-.6,enemy.position.z-.2);if(kills===3){showToast('CONTRACT COMPLETE','The Gilded Wilds are a little fairer today.');document.querySelector('#quest-text').textContent='Contract complete — find the Ledger Vault';document.querySelector('#level-toast').classList.add('show');setTimeout(()=>document.querySelector('#level-toast').classList.remove('show'),2800)}setTimeout(()=>{if(worldMode==='wilds')makeEnemy((Math.random()-.5)*50,(Math.random()-.5)*38)},9000)}}

input.newString:
setTimeout(()=>{if(worldMode==='wilds')makeEnemy((Math.random()-.5)*50,(Math.random()-.5)*38)},9000)}}

function attack(sweep=false){if(modalOpen)return;if(attackTimer>0)return;attackTimer=sweep?.62:.38;body.userData.swing=1;let nearest=null,dist=Infinity;for(const e of enemies){const d=player.position.distanceTo(e.position);if(d<dist){dist=d;nearest=e}}if(nearest&&dist<(sweep?5.4:3.8)){const amount=(sweep?36:24)+Math.floor(Math.random()*9);damageEnemy(nearest,amount);if(sweep){for(const e of [...enemies])if(e!==nearest&&player.position.distanceTo(e.position)<4.4)damageEnemy(e,Math.floor(amount*.62))}}}
function dodge(){if(stamina<22||dodgeTimer>0)return;stamina-=22;dodgeTimer=.45;player.userData.dodge=1;}
function closestTarget(max){let target=null,d=max;for(const e of enemies){const q=player.position.distanceTo(e.position);if(q<d){d=q;target=e}}for(const item of drops){const q=player.position.distanceTo(item.g.position);if(q<d){d=q;target=item}}if(player.position.distanceTo(new THREE.Vector3(39,0,-24))<d)target={portal:true};return target}
function interact(){const target=closestTarget(3.2);if(!target)return;if(target.portal){enterDungeon();return}if(target.item){const ix=drops.indexOf(target);scene.remove(target.g);drops.splice(ix,1);inventory.unshift(target.item);renderInventory();document.querySelector('#bag-count').textContent=String(inventory.length).padStart(2,'0');showToast('LOOT ACQUIRED',`${target.item.rarity} · ${target.item.name}`);return}}
function enterDungeon(){if(worldMode==='vault')return;const fade=document.querySelector('#screen-fade');fade.classList.add('active');setTimeout(()=>{worldMode='vault';player.position.set(0,0,10);for(const e of [...enemies]){scene.remove(e);enemies.splice(enemies.indexOf(e),1)}for(const d of [...drops]){scene.remove(d.g);drops.splice(drops.indexOf(d),1)}scene.background.set('#27313b');scene.fog.color.set('#27313b');scene.fog.density=.016;groundMat.color.set('#55534a');for(let i=0;i<5;i++)makeEnemy(-7+i*3.5,-8-i*3,i===4);document.querySelector('#dungeon-card').classList.remove('show');showToast('THE LEDGER VAULT','The deeper the vault, the richer the spoils.');fade.classList.remove('active')},650)}
function leaveDungeon(){if(worldMode!=='vault')return;const fade=document.querySelector('#screen-fade');fade.classList.add('active');setTimeout(()=>{worldMode='wilds';player.position.set(39,0,-18);scene.background.set('#a9b5a0');scene.fog.color.set('#a9b5a0');scene.fog.density=.0095;groundMat.color.set('#758367');for(const e of [...enemies]){scene.remove(e);enemies.splice(enemies.indexOf(e),1)}for(let i=0;i<6;i++)makeEnemy((Math.random()-.5)*50,(Math.random()-.5)*38);fade.classList.remove('active')},650)}
function renderInventory(){const grid=document.querySelector('#inventory-grid');grid.innerHTML='';const slots=Math.max(16,Math.ceil((inventory.length+4)/4)*4);for(let i=0;i<slots;i++){const item=inventory[i];const cell=document.createElement('button');cell.className='inventory-cell'+(item?.id===selectedItem?.id?' active':'');if(item){cell.style.setProperty('--item-color',item.color);cell.innerHTML=`${gearIcon(item.type)}<small>${item.name}</small><i>${item.rarity.slice(0,3)}</i>`;cell.addEventListener('click',()=>selectItem(item))}grid.append(cell)}document.querySelector('#inventory-capacity').textContent=`${inventory.length} / 32`}
function selectItem(item){selectedItem=item;renderInventory();const detail=document.querySelector('#item-detail');detail.innerHTML=`<div class="detail-icon" style="color:${item.color}">${gearIcon(item.type)}</div><div><div class="detail-name">${item.name}</div><div class="detail-type" style="color:${item.color}">${item.rarity} ${item.type.toUpperCase()} · ITEM LEVEL ${item.level}</div><div class="detail-stats"><span>+${item.power}</span> Might<br><span>+${Math.floor(item.power*.55)}</span> Resolve<br><span>+${Math.floor(item.power*.28)}</span> Haste<br><small>“For the people, not the pockets.”</small></div></div>`;document.querySelector('#equip-btn').disabled=false;document.querySelector('#equip-btn').textContent='EQUIP ITEM'}
function openInventory(){modalOpen=true;document.querySelector('#modal-backdrop').classList.add('open');renderInventory()}
function closeInventory(){modalOpen=false;document.querySelector('#modal-backdrop').classList.remove('open')}
function toggleJournal(){document.querySelector('#journal-backdrop').classList.toggle('open');modalOpen=document.querySelector('#journal-backdrop').classList.contains('open')}
// input & touch
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyI')modalOpen?closeInventory():openInventory();if(e.code==='KeyJ')toggleJournal();if(e.code==='KeyM')document.querySelector('.minimap').classList.toggle('map-expanded');if(e.code==='Digit1')attack();if(e.code==='Digit2')attack(true);if(e.code==='Digit3'){showToast('RALLYING CRY','Your resolve surges.');stamina=Math.min(100,stamina+28)}if(e.code==='Digit4'){health=Math.min(100,health+35);document.querySelector('.bar.hp span').style.width=health+'%';showToast('FIELD TONIC','Vitality restored.')}if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge()});window.addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointerdown',e=>{if(e.button===0){dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)} });canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;yaw-=dx*.004;pitch=Math.max(.08,Math.min(.62,pitch+dy*.003));lastX=e.clientX;lastY=e.clientY});canvas.addEventListener('pointerup',e=>{if(dragging){const moved=Math.abs(e.clientX-lastX)+Math.abs(e.clientY-lastY);dragging=false;if(moved<8)attack()}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
for(const [id,code] of [['mobile-up','KeyW'],['mobile-down','KeyS'],['mobile-left','KeyA'],['mobile-right','KeyD']]){const el=document.querySelector('#'+id);el.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;el.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>el.addEventListener(ev,()=>keys[code]=false))}document.querySelector('#mobile-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});
document.querySelector('#bag-btn').onclick=openInventory;document.querySelector('#modal-close').onclick=closeInventory;document.querySelector('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeInventory()});document.querySelector('#journal-close').onclick=toggleJournal;document.querySelector('#journal-backdrop').addEventListener('click',e=>{if(e.target.id==='journal-backdrop')toggleJournal()});document.querySelector('#equip-btn').onclick=()=>{if(selectedItem){document.querySelector('.weapon-chip small').innerHTML=selectedItem.name.toUpperCase().replace(' ','<br>');showToast('GEAR EQUIPPED',selectedItem.name);closeInventory()}};document.querySelector('#map-btn').onclick=()=>document.querySelector('.minimap').classList.toggle('map-expanded');document.querySelector('#sound-btn').onclick=e=>{e.currentTarget.classList.toggle('muted');e.currentTarget.textContent=e.currentTarget.classList.contains('muted')?'♫̸':'♫'};document.querySelector('#enter-dungeon').onclick=enterDungeon;

