for(const d of drops){d.g.rotation.y+=dt*.8;d.g.position.y=.12+Math.sin(clock.elapsedTime*2+d.item.id%10)*.08;d.g.children[1].rotation.z+=dt*.7}
const targetCam=player.position.clone().add(new THREE.Vector3(Math.sin(yaw)*10,6+pitch*4,Math.cos(yaw)*10));camera.position.lerp(targetCam,1-Math.exp(-dt*5));const look=player.position.clone().add(new THREE.Vector3(0,1.35,0));camera.lookAt(look);
}
